// The clock's weather is a particle effect, not a forecast readout:
// snow falls, rain streaks, fog drifts. Anything we have no effect for
// clears the slot so the clock goes back to its normal face.
const CONDITIONS = {
    snowy: { condition: 'snow', intensity: 6 },
    'snowy-rainy': { condition: 'snow', intensity: 4 },
    rainy: { condition: 'rain', intensity: 5 },
    pouring: { condition: 'rain', intensity: 10 },
    fog: { condition: 'fog', intensity: 6 },
    hail: { condition: 'snow', intensity: 9 },
};

const SLOT = 2;
const match = CONDITIONS[msg.payload];

if (!match) {
    // A scene stays in its slot and replays until cleared -- it does not
    // expire on its own. Clearing is how weather stops.
    msg.action = 'glance_clock.clear_leds';
    msg.payload = { slot: SLOT };
    return msg;
}

msg.action = 'glance_clock.set_scene';
msg.payload = {
    mode: 'watchface',
    slot: SLOT,
    steps: [
        {
            type: 'weather',
            condition: match.condition,
            position: 'full',
            intensity: match.intensity,
            seconds: 60,
        },
    ],
};
return msg;
